import{_ as o,o as e,c as a,a2 as d}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"扩展能力怎么选","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/extensions.md","filePath":"zh/guides/extensions.md","lastUpdated":1790952322000}'),r={name:"zh/guides/extensions.md"};function s(l,t,h,i,n,c){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="扩展能力怎么选" tabindex="-1">扩展能力怎么选 <a class="header-anchor" href="#扩展能力怎么选" aria-label="Permalink to &quot;扩展能力怎么选&quot;">​</a></h1><p>Memoh 有五种给 Bot 加能力的方式。单看名字很容易混，摆在一起就清楚了——所以直接摆在一起。</p><table tabindex="0"><thead><tr><th>扩展方式</th><th>它是什么</th><th>放在哪 / 怎么触发</th><th>适合什么</th></tr></thead><tbody><tr><td><a href="./skills.html">技能</a></td><td>改变 Bot 做事方式的 <code>SKILL.md</code> 提示模块</td><td>在 Bot 工作区的 <code>/data/skills/</code> 下，从 <strong>Skills</strong> 标签页管理；在对话中唤起</td><td>那些本来每次都要重打一遍的流程和工作习惯</td></tr><tr><td><a href="./hooks.html">Hooks</a></td><td>写在 <code>hooks.json</code> 里、可以运行命令或工具的事件规则</td><td>在 <code>/data/.memoh/hooks.json</code>，从 <strong>Hooks</strong> 标签页编辑；在 <code>PreToolUse</code>、<code>TurnEnd</code> 这类生命周期事件上触发</td><td>固定节点上的检查和附带动作，全程不经过聊天</td></tr><tr><td><a href="./mcp.html">MCP</a></td><td>到外部 MCP 工具服务器的连接</td><td>按 Bot 在 <strong>MCP</strong> 标签页配置，Stdio 或 Remote 连接；发现的工具在对话中使用</td><td>接入一个本身就带 MCP server 的工具</td></tr><tr><td><a href="./connectors.html">连接器</a></td><td>到 GitHub、Notion 这类服务的 OAuth 或 API Key 绑定</td><td>从应用市场的 <strong>Connectors</strong> 标签页连接，在 Bot 的 <strong>Connectors</strong> 标签页管理；服务的工具出现在对话里</td><td>让 Bot 用你在某个托管服务上的账号做事</td></tr><tr><td><a href="./supermarket.html">应用市场</a></td><td>Memoh 内置目录：一键安装打包好的应用——技能连同它的依赖和连接器</td><td>在 <strong>设置</strong> 下；装好的内容落进目标 Bot 自己的各个标签页</td><td>直接拿到现成能力，不用自己拼零件</td></tr></tbody></table><p>不管能力从哪条路进来，最后都汇到同一个地方：连接器和 MCP 的工具在对话里与工作区工具并列出现，装好的技能出现在 Bot 的 <strong>Skills</strong> 标签页里，和手写的没有两样。</p><h2 id="该用哪个" tabindex="-1">该用哪个？ <a class="header-anchor" href="#该用哪个" aria-label="Permalink to &quot;该用哪个？&quot;">​</a></h2><ul><li>想改 Bot 的做事方式 → <a href="./skills.html">技能</a>。</li><li>想在某个事件点自动做事 → <a href="./hooks.html">Hooks</a>。</li><li>想接一个有 MCP server 的工具 → <a href="./mcp.html">MCP</a>。</li><li>想让 Bot 用你的 GitHub/Notion 账号 → <a href="./connectors.html">连接器</a>。</li><li>想一键装现成的一套 → <a href="./supermarket.html">应用市场</a>。</li></ul><div class="tip custom-block"><p class="custom-block-title">它们可以叠着用</p><p>这五种不是互斥选项。应用市场装的一个应用可能同时带来技能和连接器，Hook 也可以看住经 MCP 接进来的工具。按上面的问题选，而不是每个 Bot 只挑一种。</p></div><h2 id="从哪开始" tabindex="-1">从哪开始 <a class="header-anchor" href="#从哪开始" aria-label="Permalink to &quot;从哪开始&quot;">​</a></h2><p>每种方式都有完整的一页，展开这张表压缩掉的细节：</p><ul><li><a href="./skills.html">技能</a>——<code>SKILL.md</code> 的写法、技能状态、收编发现的技能。</li><li><a href="./hooks.html">Hooks</a>——事件目录、配置结构、怎么测试一条规则。</li><li><a href="./mcp.html">MCP</a>——Stdio 与 Remote 连接、OAuth、工具发现。</li><li><a href="./connectors.html">连接器</a>——连接状态、重新授权、工具命名空间。</li><li><a href="./supermarket.html">应用市场</a>——浏览目录、安装到 Bot。</li></ul><p>拿不定主意就先逛应用市场——装一个现成的包，先看看成品长什么样，再动手搭自己的。</p>',11)])])}const u=o(r,[["render",s]]);export{p as __pageData,u as default};
